(async () => {
  const out = { title: "", body: "", url: location.href, author: "", kind: "article", transcriptUnavailable: false };
  const clean = (s) => (s || "").replace(/ /g, " ").replace(/[ \t]+/g, " ").replace(/\n{3,}/g, "\n\n").trim();

  try {
    const isYouTube = /(^|\.)youtube\.com$/.test(location.hostname) && location.pathname === "/watch";

    if (isYouTube) {
      out.kind = "video";

      // Bootstrap blob may be stale after client-side nav; fallback to parsing inline script.
      let pr = window.ytInitialPlayerResponse;
      const currentId = new URLSearchParams(location.search).get("v");
      if (!pr || pr?.videoDetails?.videoId !== currentId) {
        for (const s of document.querySelectorAll("script")) {
          const m = s.textContent && s.textContent.match(/ytInitialPlayerResponse\s*=\s*(\{.+?\})\s*;\s*(?:var|const|let|<\/script>|$)/s);
          if (m) { try { pr = JSON.parse(m[1]); } catch (_) {} }
          if (pr?.videoDetails?.videoId === currentId) break;
        }
      }

      out.title = clean(pr?.videoDetails?.title || document.title.replace(/ - YouTube$/, ""));
      out.author = clean(pr?.videoDetails?.author || "");

      const tracks = pr?.captions?.playerCaptionsTracklistRenderer?.captionTracks || [];
      // Prefer human-made English; fall back to auto-generated, then any language.
      const pick =
        tracks.find((t) => (t.languageCode || "").startsWith("en") && t.kind !== "asr") ||
        tracks.find((t) => (t.languageCode || "").startsWith("en")) ||
        tracks[0];

      if (pick && pick.baseUrl) {
        try {
          const res = await fetch(pick.baseUrl + "&fmt=json3");
          const data = await res.json();
          const lines = [];
          for (const ev of data.events || []) {
            const text = (ev.segs || []).map((s) => s.utf8).join("");
            const t = clean(text);
            // json3 pads with empty timing events; keeping them would produce a
            // transcript that is mostly blank lines.
            if (t) lines.push(t);
          }
          out.body = lines.join(" ").replace(/\s+/g, " ").trim();
        } catch (_) {
          out.body = "";
        }
      }

      // Panel fallback (Obsidian Web Clipper approach). Covers both classic and new panels.
      if (!out.body) {
        const sleep = (ms) => new Promise((r) => setTimeout(r, ms));
        const PANELS = 'ytd-engagement-panel-section-list-renderer[target-id="engagement-panel-searchable-transcript"],' +
                       'ytd-engagement-panel-section-list-renderer[target-id="PAmodern_transcript_view"]';

        const readPanel = () => {
          for (const panel of document.querySelectorAll(PANELS)) {
            const segs = panel.querySelectorAll("ytd-transcript-segment-renderer");
            if (segs.length) {
              // Each segment has timestamp (navigation UI) and text; keep text only.
              return [...segs]
                .map((s) => clean(s.innerText).replace(/^\d{1,2}:\d{2}(:\d{2})?\s*/, ""))
                .filter(Boolean)
                .join(" ");
            }
            const strings = panel.querySelectorAll("span.yt-core-attributed-string");
            if (strings.length > 4) {
              return [...strings]
                .map((s) => clean(s.innerText))
                .filter((t) => t && !/^\d{1,2}:\d{2}(:\d{2})?$/.test(t) && t !== "Transcript")
                .join(" ");
            }
          }
          return "";
        };

        out.body = readPanel();

        if (!out.body) {
          // Open panel as user would: expand description, then click "Show transcript".
          document.querySelector("#expand, tp-yt-paper-button#expand")?.click();
          await sleep(600);
          const controls = document.querySelectorAll("button,[role='button'],yt-chip-cloud-chip-renderer,tp-yt-paper-tab");
          for (const c of controls) {
            const label = ((c.innerText || "") + " " + (c.getAttribute("aria-label") || "")).toLowerCase();
            if (label.includes("transcript")) { try { c.click(); } catch (_) {} }
          }
          // The panel loads its segments lazily over the network.
          for (let i = 0; i < 20 && !out.body; i++) {
            await sleep(400);
            out.body = readPanel();
          }
        }
      }

      if (!out.body) {
        out.transcriptUnavailable = true;
        const desc = clean(pr?.videoDetails?.shortDescription || "");
        // Distinguish: no captions (never fixable) vs. panel failed (try signed in).
        const hadTrack = tracks.length > 0;
        out.body = [
          hadTrack
            ? "This video has captions, but YouTube withheld transcript text. " +
              "Sign in to YouTube in this panel and clip again."
            : "This video has no captions, so there is no transcript to capture.",
          desc ? "\n\n## Description\n\n" + desc : "",
        ].join("");
      }
      return JSON.stringify(out);
    }

    // Prefer semantic content container; fallback to body avoids nav/footers.
    out.title = clean(
      document.querySelector("meta[property='og:title']")?.content || document.title
    );
    out.author = clean(
      document.querySelector("meta[name='author']")?.content ||
      document.querySelector("meta[property='article:author']")?.content ||
      document.querySelector("meta[property='og:site_name']")?.content || ""
    );

    const el =
      document.querySelector("article") ||
      document.querySelector("main") ||
      document.querySelector("[role='main']") ||
      document.body;

    const clone = el.cloneNode(true);
    for (const junk of clone.querySelectorAll("script,style,noscript,nav,header,footer,aside,iframe,svg,form")) {
      junk.remove();
    }
    out.body = clean(clone.innerText || "");
    if (!out.body) out.body = clean(document.body.innerText || "");
  } catch (e) {
    out.body = out.body || "";
    out.title = out.title || document.title || location.href;
  }
  return JSON.stringify(out);
})()
